SELECT COUNT(CASE WHEN l.valueuom = 'mg/L' AND l.value < 1000 THEN 1 END) AS normal_troponin_count, COUNT(CASE WHEN l.valueuom = 'mg/L' AND l.value BETWEEN 1000 AND 1500 THEN 1 END) AS borderline_troponin_count, COUNT(CASE WHEN l.valueuom = 'mg/L' AND l.value > 1500 THEN 1 END) AS myocardial_injury_count FROM labevents l JOIN admissions a ON l.subject_id = a.subject_id AND l.hadm_id = a.hadm_id JOIN patients p ON a.subject_id = p.subject_id WHERE p.gender = 'M' AND p.anchor_age = 40 AND p.anchor_year BETWEEN 2015 AND 2016 AND (l.itemid = 1117855 OR l.itemid = 1117856) AND l.charttime BETWEEN a.admittime AND a.dischtime AND l.valueuom = 'mg/L' AND l.value < 1500;